using System;
using System.IO;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using HeronBrush.Live;
using Object = UnityEngine.Object;

// Copy to Assets/Editor in the disposable project generated by native_unity_live_fixtures.
public static class VerifyExport
{
    static void Check(bool condition, string message) { if (!condition) throw new Exception(message); }
    static void Call(object target, string method) => target.GetType().GetMethod(method, BindingFlags.Instance | BindingFlags.NonPublic).Invoke(target, null);
    static void Tick(HeronBrushLiveWindow window) {
        typeof(HeronBrushLiveWindow).GetField("nextPoll", BindingFlags.Instance | BindingFlags.NonPublic).SetValue(window, 0d);
        Call(window, "Tick");
    }
    static string Project => Directory.GetParent(Application.dataPath).FullName;
    public static void Render()
    {
        try {
            EditorSceneManager.OpenScene("Assets/Verified.unity");
            var camera=new GameObject("Verification camera").AddComponent<Camera>();
            camera.transform.position=new Vector3(3,3,-10);
            camera.transform.LookAt(new Vector3(0,2,10));
            camera.clearFlags=CameraClearFlags.SolidColor;
            camera.backgroundColor=new Color(.12f,.16f,.22f);
            camera.farClipPlane=200;
            RenderSettings.ambientLight=new Color(.15f,.15f,.15f);
            var target=new RenderTexture(960,640,24);
            camera.targetTexture=target;camera.Render();RenderTexture.active=target;
            var image=new Texture2D(960,640,TextureFormat.RGB24,false);
            image.ReadPixels(new Rect(0,0,960,640),0,0);image.Apply();
            File.WriteAllBytes(Path.Combine(Project,"unity-preview.png"),image.EncodeToPNG());
            Check(image.GetPixels32().Select(c=>(c.r,c.g,c.b)).Distinct().Count()>100,"Render is empty");
            Debug.Log("HERON_UNITY_RENDER PASS");EditorApplication.Exit(0);
        } catch(Exception e) {Debug.LogException(e);EditorApplication.Exit(2);}
    }
    public static void Run()
    {
        try {
            EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
            HeronBrushLevelImporter.Build();
            var final = GameObject.Find("preview");
            Check(final, "Final export root missing");
            Check(final.GetComponentsInChildren<MeshRenderer>().Length > 0, "Final meshes missing");
            Check(final.GetComponentsInChildren<Light>().Length > 0, "Final lights missing");
            Check(final.GetComponentsInChildren<Collider>().Length > 0, "Final collisions missing");
            int finalCollisions = final.GetComponentsInChildren<Collider>().Length;
            int finalTriggers = final.GetComponentsInChildren<Collider>().Count(c=>c.isTrigger);
            Check(finalTriggers > 0, "Final invisible triggers missing");
            Debug.Log("HERON_UNITY_FINAL renderers=" + final.GetComponentsInChildren<MeshRenderer>().Length + " colliders=" + final.GetComponentsInChildren<Collider>().Length);
            Object.DestroyImmediate(final);
            var unrelated = new GameObject("User owned object");
            var window = ScriptableObject.CreateInstance<HeronBrushLiveWindow>();
            int previousTriangles = 0;
            for (int step = 0; step < 4; ++step) {
                var fixture = Path.Combine(Project, "LiveFixtures", step.ToString());
                foreach (var file in Directory.GetFiles(Path.Combine(fixture,"Assets"), "*", SearchOption.AllDirectories)) {
                    var destination = Path.Combine(Project, file.Substring(fixture.Length + 1));
                    Directory.CreateDirectory(Path.GetDirectoryName(destination));
                    File.Copy(file,destination,true);
                }
                File.Copy(Path.Combine(fixture,".heron-brush-live.json"),Path.Combine(Project,".heron-brush-live.json"),true);
                AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);
                if (step == 0) Call(window,"Attach");
                if (step == 1) {
                    var attached = Object.FindFirstObjectByType<HeronBrushLiveRoot>();
                    var before = attached.generated;
                    typeof(HeronBrushLiveWindow).GetField("syncing",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(window,false);
                    Tick(window);
                    Check(attached.generated == before,"Paused link changed geometry");
                    typeof(HeronBrushLiveWindow).GetField("syncing",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(window,true);
                }
                Tick(window); Tick(window); Tick(window);
                var ack = JsonUtility.FromJson<HeronBrushLiveWindow.Ack>(File.ReadAllText(Path.Combine(Project,".heron-brush-live-status.json")));
                Check(ack.state == "updated", "Live update failed: " + ack.message);
                var roots = Object.FindObjectsByType<HeronBrushLiveRoot>(FindObjectsSortMode.None);
                Check(roots.Length == 1 && roots[0].generated, "Expected a single generated branch");
                var root = roots[0];
                Check(unrelated, "Unrelated object deleted");
                if (step == 0) root.transform.position = new Vector3(3,1,2);
                Check(root.transform.position == new Vector3(3,1,2), "Root transform lost");
                var branch = root.generated;
                var filters = branch.GetComponentsInChildren<MeshFilter>();
                var colliders = branch.GetComponentsInChildren<MeshCollider>();
                Check(filters.Length > 0 && colliders.Length > 0, "Live geometry/collision missing");
                if (step == 0) Check(colliders.Length == finalCollisions && colliders.Count(c=>c.isTrigger) == finalTriggers, "Final/live collision mismatch");
                var materials = branch.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).ToArray();
                Check(materials.All(m=>m && m.mainTexture && m.shader && m.shader.name != "Hidden/InternalErrorShader"), "Missing materials or shaders");
                Debug.Log("HERON_UNITY_MATERIALS total="+materials.Length+" textured="+materials.Count(m=>m.mainTexture));
                Check(colliders.All(c=>c.sharedMesh && !string.IsNullOrEmpty(AssetDatabase.GetAssetPath(c.sharedMesh))), "Nonpersistent collider");
                Check(branch.GetComponentsInChildren<Light>().Length > 0, "Live lights missing");
                int triangles = filters.Sum(f=>f.sharedMesh.triangles.Length / 3);
                if (step == 1) previousTriangles = triangles;
                if (step == 2) Check(triangles < previousTriangles, "Delete did not remove geometry");
                if (step == 3) Check(triangles == previousTriangles, "Undo did not restore geometry");
                Physics.SyncTransforms();
                int hits=0;
                foreach (var c in colliders.Where(c=>!c.isTrigger)) {
                    var b=c.bounds;
                    if(c.Raycast(new Ray(b.center+Vector3.up*(b.extents.y+1),Vector3.down),out var hit,b.size.y+2)) hits++;
                }
                Check(hits>0,"Native physics raycasts did not hit exported collision");
                Debug.Log($"HERON_UNITY_LIVE stage={step} meshes={filters.Length} triangles={triangles} colliders={colliders.Length} rayhits={hits}");
            }
            var attachedRoot = Object.FindFirstObjectByType<HeronBrushLiveRoot>();
            var previousBranch = attachedRoot.generated;
            var manifestPath=Path.Combine(Project,".heron-brush-live.json");
            var manifest=JsonUtility.FromJson<HeronBrushLiveWindow.Manifest>(File.ReadAllText(manifestPath));
            var snapshotPath=Path.Combine(Project,manifest.scene);
            var originalSnapshot=File.ReadAllText(snapshotPath);
            var broken=JsonUtility.FromJson<HeronBrushLiveWindow.Snapshot>(originalSnapshot);
            broken.entities.First(e=>!string.IsNullOrEmpty(e.mesh)).mesh="meshes/missing.obj";
            manifest.revision="verify-failed-import";
            File.WriteAllText(snapshotPath,JsonUtility.ToJson(broken));
            File.WriteAllText(manifestPath,JsonUtility.ToJson(manifest));
            Tick(window); Tick(window);
            var failure=JsonUtility.FromJson<HeronBrushLiveWindow.Ack>(File.ReadAllText(Path.Combine(Project,".heron-brush-live-status.json")));
            Check(failure.state=="error" && attachedRoot.generated==previousBranch,"Failed import destroyed previous map");
            File.WriteAllText(snapshotPath,originalSnapshot);
            typeof(HeronBrushLiveWindow).GetField("failedRevision",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(window,null);
            Tick(window);
            Check(attachedRoot.revision==manifest.revision,"Retry did not recover");
            Object.DestroyImmediate(window);
            EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/Verified.unity");
            EditorSceneManager.OpenScene("Assets/Verified.unity");
            Check(Object.FindObjectsByType<MeshCollider>(FindObjectsSortMode.None).All(c=>c.sharedMesh),"Reload lost collider meshes");
            Debug.Log("HERON_UNITY_CHECK PASS");
            EditorApplication.Exit(0);
        } catch(Exception e) { Debug.LogException(e); EditorApplication.Exit(2); }
    }
}
